        { id: "notification-sms", label: "SMS", value: "sms" },
        {
          id: "notification-push",
          label: "Push Notifications",
          value: "push-notifications",
        },
      ];

      function HeaderSection() {
        return `
          <header class="hero">
            <p class="eyebrow">Preferences</p>
            <h1>Choose your notification channel</h1>
            <p class="intro">
              Tell us where updates should land so product alerts feel timely,
              useful, and easy to manage.
            </p>
          </header>
        `;
      }

