         border-radius: 999px;
         background: var(--text);
         color: #ffffff;
         padding: 0.75rem 1rem;
         font-weight: 700;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .page-shell {
         display: grid;
         min-height: 100vh;
         place-items: center;
         padding: clamp(1rem, 4vw, 3rem);
       }

       .card {
         width: min(100%, 42rem);
         border: 1px solid rgba(215, 222, 234, 0.9);
         border-radius: 1.5rem;
         background: rgba(255, 255, 255, 0.92);
         box-shadow: 0 1.5rem 4rem rgba(23, 32, 51, 0.12);
         overflow: hidden;
       }

       .hero {
         padding: clamp(1.5rem, 5vw, 3rem);
         border-bottom: 1px solid var(--border);
         background:
           linear-gradient(135deg, rgba(48, 92, 255, 0.12), rgba(48, 92, 255, 0)),
           var(--surface);
       }

       .eyebrow {
         margin: 0 0 0.75rem;
         color: var(--accent-strong);
         font-size: 0.85rem;
         font-weight: 800;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 7vw, 3.5rem);
         line-height: 1;
         letter-spacing: -0.05em;
       }

       .intro {
         max-width: 34rem;
         margin: 1rem 0 0;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 1.5rem;
         padding: clamp(1.5rem, 5vw, 3rem);
       }

       .form-field {
         display: grid;
         gap: 1rem;
       }

       fieldset {
         min-width: 0;
         margin: 0;
         padding: 0;
         border: 0;
       }

       legend {
         margin-bottom: 0.35rem;
         padding: 0;
         color: var(--text);
         font-size: 1.2rem;
         font-weight: 800;
       }

       .required-note,
       .help-text {
         margin: 0;
         color: var(--muted);
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .required-marker {
         color: var(--accent-strong);
       }

       .radio-list {
         display: grid;
         gap: 0.75rem;
         margin-top: 1rem;
       }

       .radio-option {
         position: relative;
       }

       .radio-option input {
         position: absolute;
         inset: 1.15rem auto auto 1.15rem;
         width: 1.25rem;
         height: 1.25rem;
         margin: 0;
         accent-color: var(--accent);
       }

       .radio-option label {
         display: flex;
         min-height: 3.5rem;
         align-items: center;
         border: 1px solid var(--border);
         border-radius: 1rem;
         background: #ffffff;
         color: var(--text);
         cursor: pointer;
         font-weight: 700;
         padding: 1rem 1rem 1rem 3.25rem;
         transition:
           border-color 160ms ease,
           box-shadow 160ms ease,
           transform 160ms ease;
       }

       .radio-option label:hover {
         border-color: #8ea4ff;
         box-shadow: 0 0.75rem 1.75rem rgba(48, 92, 255, 0.12);
         transform: translateY(-1px);
       }

       .radio-option input:focus-visible + label {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .radio-option input:checked + label {
         border-color: var(--accent);
         background: linear-gradient(135deg, rgba(48, 92, 255, 0.1), #ffffff);
         box-shadow: inset 0 0 0 1px var(--accent);
       }

       .actions {
         display: flex;
         align-items: center;
         gap: 1rem;
         flex-wrap: wrap;
       }

       button {
         min-height: 2.75rem;
         border: 0;
         border-radius: 999px;
         background: var(--accent);
         color: #ffffff;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         padding: 0.85rem 1.35rem;
         transition:
           background-color 160ms ease,
           box-shadow 160ms ease,
           transform 160ms ease;
       }

       button:hover {
         background: var(--accent-strong);
         box-shadow: 0 0.85rem 1.75rem rgba(48, 92, 255, 0.24);
         transform: translateY(-1px);
       }

       button:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .status-message {
         min-height: 1.5rem;
         margin: 0;
         color: var(--success-text);
         font-weight: 700;
       }

       .status-message:not(:empty) {
         border-radius: 0.85rem;
         background: var(--success-bg);
         padding: 0.75rem 1rem;
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         .hero,
         .radio-option label,
         .status-message:not(:empty) {
           border: 1px solid CanvasText;
           background: Canvas;
         }

         button {
           border: 1px solid ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>

     <script>
       const notificationOptions = [
         { id: "notification-email", label: "Email", value: "email" },
         { id: "notification-sms", label: "SMS", value: "sms" },
         {
           id: "notification-push",
           label: "Push Notifications",
           value: "push-notifications",
         },
       ];

       function HeaderSection() {
         return `
           <header class="hero">
             <p class="eyebrow">Preferences</p>
             <h1>Choose your notification channel</h1>
             <p class="intro">
               Tell us where updates should land so product alerts feel timely,
               useful, and easy to manage.
             </p>
           </header>
         `;
       }

       function RadioOption(option) {
         return `
           <div class="radio-option">
             <input
               id="${option.id}"
               type="radio"
               name="notificationPreference"
               value="${option.value}"
               required
             >
             <label for="${option.id}">${option.label}</label>
           </div>
         `;
       }

       function NotificationForm() {
         return `
           <form id="notification-form">
             <p class="required-note">
               Fields marked with <span class="required-marker" aria-hidden="true">*</span>
               are required.
             </p>

             <div class="form-field">
               <fieldset aria-describedby="notification-help">
                 <legend>
                   How do you prefer to receive notifications?
                   <span class="required-marker" aria-hidden="true">*</span>
                 </legend>
                 <p id="notification-help" class="help-text">
                   Select one option. You can update this preference later.
                 </p>
                 <div class="radio-list">
                   ${notificationOptions.map(RadioOption).join("")}
                 </div>
               </fieldset>
             </div>

             <div class="actions">
               <button type="submit">Save preference</button>
               <p id="form-status" class="status-message" aria-live="polite"></p>
             </div>
           </form>
         `;
       }

       function App() {
         return `
           <main id="main-content" class="page-shell">
             <section class="card" aria-labelledby="page-title">
               ${HeaderSection().replace("<h1>", '<h1 id="page-title">')}
               ${NotificationForm()}
             </section>
           </main>
         `;
       }

       document.querySelector("#app").innerHTML = App();

       document
         .querySelector("#notification-form")
         .addEventListener("submit", (event) => {
           event.preventDefault();

           const selected = document.querySelector(
             'input[name="notificationPreference"]:checked'
           );

           if (!selected) {
             document.querySelector("#notification-email").focus();
             return;
           }

           const selectedLabel = document.querySelector(
             `label[for="${selected.id}"]`
           ).textContent;

           document.querySelector(
             "#form-status"
           ).textContent = `Preference saved: ${selectedLabel}.`;
         });
     </script>
   </body>
 </html>

')
